contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint64 ts, uint amount) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        // Set up a known valid pastBlockTime first, if possible.
        // Use a call with exactly 10 ether and a timestamp we choose...
        // But we cannot control block.timestamp. Instead, we just call once.
        // To make the rule checkable, we drive the fallback with exactly 10 ether.
        // The precondition for success is timestamp > pastBlockTime, which initially is 0.
        // The checker runs once, so it must be fresh c.
        // pastBlockTime is initially 0.
        // We need ts as a parameter but the actual timestamp is block.timestamp.
        // We cannot force block.timestamp to equal ts. So the rule should relate the
        // observed pastBlockTime before and after, and the revert status.

        // Read before state.
        uint beforeBal = address(c).balance;
        uint beforeTime = c.pastBlockTime();

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterTime = c.pastBlockTime();
        uint afterBal = address(c).balance;

        // General rule:
        // If the call reverted, then the pastBlockTime must not have changed,
        // and the balance must not have changed.
        // If it did not revert, then pastBlockTime == block.timestamp and
        // it was > beforeTime, and the balance change is either +10 ether (if block.number % 15 != 0)
        // or -beforeBal (if block.number % 15 == 0).
        // We can express this without knowing block.timestamp by observing that
        // afterTime > beforeTime and afterTime == block.timestamp is not observable directly.
        // But we can observe the balance change.

        // We can write a rule about the balance:
        // If not reverted and block.number % 15 != 0, then afterBal == beforeBal + amount.
        // If not reverted and block.number % 15 == 0, then afterBal == 0.
        // If reverted, afterBal == beforeBal and afterTime == beforeTime.
        // This is a general rule over all inputs.

        // However, block.number is not directly available in the test contract...
        // Actually it is: block.number is available in Solidity.

        if (reverted) {
            assert(afterTime == beforeTime && afterBal == beforeBal);
        } else {
            assert(afterTime > beforeTime &&
                   ((block.number % 15 != 0 && afterBal == beforeBal + amount) ||
                    (block.number % 15 == 0 && afterBal == 0)));
        }
    }

    receive() external payable {}
}

