contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, uint nextTimestamp) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient balance");

        // Read the state that the rule depends on.
        uint beforeTime = c.pastBlockTime();

        // The precondition on the parameter that makes the call expected to succeed.
        require(nextTimestamp > beforeTime, "timestamp must be strictly increasing");

        // Make the deciding call.  The fallback uses block.timestamp, so the rule
        // is expressed in terms of the state read before the call and the
        // parameter that would have been a valid new timestamp.
        (bool ok, ) = address(c).call{value: amount}("");

        // Read the after-value through the public getter.
        uint afterTime = c.pastBlockTime();

        // General rule: the call succeeds, and the recorded time is updated to a
        // strictly larger value (the call cannot leave pastBlockTime unchanged).
        assert(ok && afterTime > beforeTime);
    }
}

