contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(bool attemptAfter) public payable {
        require(address(this).balance >= 10 ether);

        // Optionally wait for a future timestamp by first making a call? Cannot control block.timestamp.
        // Instead, establish a prior pastBlockTime by an initial successful call, then test a second call.
        // First call: succeeds only if block.timestamp > pastBlockTime (initial 0) and pays 10 ether.
        // We use `attemptAfter` to decide whether to make the second call in the same test.
        // Since block.timestamp is unpredictable, we cannot force monotonicity in a single run.
        // But the property we test: after exactly one successful 10-ether fallback call,
        // pastBlockTime == that call's block.timestamp, and the balance either stayed or dropped by
        // exactly (beforeBalance - 10 ether) if the drain condition held? Actually we cannot observe
        // block.number % 15 at the call site. Instead, we test the general rule:
        // A 10-ether fallback call with msg.value == 10 ether either reverts (when timestamp not greater)
        // or succeeds, in which case pastBlockTime equals the block.timestamp of the call, and the
        // balance after the call is either the same as (beforeBalance + 10 ether) or exactly 0.

        uint beforeBalance = address(c).balance;
        uint beforePastBlockTime = c.pastBlockTime();
        uint beforeTestBalance = address(this).balance;

        bool reverted;
        try c.fallback{value: 10 ether}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint afterPastBlockTime = c.pastBlockTime();
            uint afterBalance = address(c).balance;
            // If successful, pastBlockTime must equal the current block.timestamp.
            // The balance must be either beforeBalance + 10 ether (no drain) or 0 (drain).
            // Since beforeBalance could be 0 or non-zero, and drain sends entire balance
            // to msg.sender (this contract), the new balance is 0 in the drain case.
            assert(afterPastBlockTime == block.timestamp);
            assert(afterBalance == beforeBalance + 10 ether || afterBalance == 0);
        } else {
            assert(c.pastBlockTime() == beforePastBlockTime);
            assert(address(c).balance == beforeBalance);
            assert(address(this).balance == beforeTestBalance);
        }
    }
}

