        // Ensure the contract's balance is exactly amount for the deciding call:
        // (we can't control c.balance directly, but we can ensure it comes from our msg.value in this test)
        require(address(this).balance >= amount);

        // Record before-values
        uint b0 = address(c).balance;
        uint t0 = c.pastBlockTime();

        // Make the deciding call
        c.fallback{value: amount}();

        // After-call reads
        uint b1 = address(c).balance;
        uint t1 = c.pastBlockTime();

        // The general rule:
        // - pastBlockTime is updated to the current block timestamp
        // - if block.number is not divisible by 15, the balance is exactly the msg.value just sent
        // - if block.number is divisible by 15, the balance becomes zero (sent to msg.sender)
        if (block.number % 15 == 0) {
            assert(t1 == block.timestamp && b1 == 0);
        } else {
            assert(t1 == block.timestamp && b1 == amount);
        }
    }
}

