    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        require(amount == 10 ether, "must send exactly 10 ether");
        require(address(this).balance >= amount, "insufficient test balance");

        uint256 prevTimestamp = c.pastBlockTime();
        uint256 contractBalanceBefore = address(c).balance;
        uint256 testBalanceBefore = address(this).balance;

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 postTimestamp = c.pastBlockTime();
        uint256 contractBalanceAfter = address(c).balance;
        uint256 testBalanceAfter = address(this).balance;

        if (!reverted) {
            assert(postTimestamp == block.timestamp);
            assert(postTimestamp > prevTimestamp);
            assert(contractBalanceAfter < contractBalanceBefore + amount);
            assert(testBalanceAfter <= testBalanceBefore - amount);
        } else {
            assert(postTimestamp == prevTimestamp);
            assert(contractBalanceAfter == contractBalanceBefore);
            assert(testBalanceAfter == testBalanceBefore);
        }
    }

    receive() external payable {}
}

