contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint advance) public payable {
        require(amount == 10 ether);
        require(address(this).balance >= amount);

        uint beforeBalance = address(this).balance;
        uint cBalanceBefore = address(c).balance;

        uint beforeTimestamp = c.pastBlockTime();

        // Advance time so that block.timestamp > pastBlockTime is satisfied.
        // In a real EVM test environment, block.timestamp can be influenced by
        // transaction ordering, but here we just use the current time and assume
        // the checker runs with a fresh state and the current timestamp is greater
        // than 0. Since pastBlockTime starts at 0, any positive timestamp works.
        // However, if the checker allows setting timestamp, we cannot; we just
        // rely on the fact that block.timestamp is generally > 0.
        // To make the rule robust, we require that the current block.timestamp
        // is strictly greater than pastBlockTime. This is a precondition that
        // the checker should satisfy for a fresh c.
        require(block.timestamp > beforeTimestamp);

        // Only proceed if the current block number is divisible by 15,
        // because only then does the transfer happen. This is a precondition
        // on the environment, not on c's state.
        require(block.number % 15 == 0);

        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The accepted rule: after a successful call that sends 10 ether and
        // meets the conditions, c's balance is zero and the caller's balance
        // increases by c's previous balance (minus nothing, since gas is not
        // considered here). Also, c's pastBlockTime is updated to the current
        // block.timestamp.
        // We assert the more specific and strong property that c's balance is zero.
        // We also assert that if the call did not revert, c's balance is zero.
        // However, the rule must be general for all inputs that satisfy the
        // preconditions. The function should not revert in this case because
        // the conditions are met. But we still use the revert flag to guard the
        // assertion.
