        }

        uint afterPastBlockTime = c.pastBlockTime();
        uint afterContractBalance = address(c).balance;

        bool conditionsMet = (amount == 10 ether) && (block.timestamp > beforePastBlockTime);
        assert(reverted != conditionsMet);
        assert(!conditionsMet || afterPastBlockTime == block.timestamp);
        assert(!conditionsMet || block.number % 15 != 0 || afterContractBalance == 0);
    }

    function doFallback(uint amount) external payable {
        require(msg.sender == address(this), "only self");
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok, "fallback call failed");
    }
}
